create table branches(id serial primary key,name text not null,lat float8,lng float8,radius int default 150,qr_token text default gen_random_uuid()::text);
create table profiles(id uuid primary key references auth.users on delete cascade,full_name text,role text default 'employee' check(role in('admin','employee','driver')),branch_id int references branches,shift_start time default '08:00',shift_end time default '19:00',off_day smallint default 0,active boolean default true);
create table attendance(id bigserial primary key,user_id uuid references profiles,branch_id int references branches,kind text check(kind in('in','out')),lat float8,lng float8,note text,edited_by uuid references profiles,created_at timestamptz default now());
create table leaves(id bigserial primary key,user_id uuid references profiles,from_date date,to_date date,reason text,status text default 'pending' check(status in('pending','approved','rejected')),created_at timestamptz default now());
create table audit(id bigserial primary key,actor uuid references profiles,action text,detail text,created_at timestamptz default now());
create function is_admin() returns boolean language sql security definer stable set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='admin')$$;
create function new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email));return new;end$$;
create trigger on_signup after insert on auth.users for each row execute function new_user();
create function mark(k text,la float8,ln float8,tok text) returns text language plpgsql security definer set search_path=public as $$
declare p profiles;b branches;d float8;l attendance;
begin
select * into p from profiles where id=auth.uid();
select * into b from branches where qr_token=tok;
if b.id is null then raise exception 'QR kod noto''g''ri'; end if;
if p.branch_id is not null and p.branch_id<>b.id and p.role<>'driver' then raise exception 'Bu boshqa filialning QR kodi'; end if;
d:=12742000*asin(sqrt(power(sin(radians(la-b.lat)/2),2)+cos(radians(b.lat))*cos(radians(la))*power(sin(radians(ln-b.lng)/2),2)));
if d>b.radius then raise exception 'Filial hududidan % m uzoqdasiz',round(d); end if;
select * into l from attendance where user_id=p.id and created_at>=date_trunc('day',now() at time zone 'Asia/Tashkent') at time zone 'Asia/Tashkent' order by created_at desc limit 1;
if k='in' and l.kind='in' then raise exception 'Siz allaqachon "Keldim" bosgansiz'; end if;
if k='out' and (l.id is null or l.kind='out') then raise exception 'Avval "Keldim" bosing'; end if;
insert into attendance(user_id,branch_id,kind,lat,lng) values(p.id,b.id,k,la,ln);
return 'ok';end$$;
create function qr_of(bid int) returns text language plpgsql security definer set search_path=public as $$begin if not is_admin() then raise exception 'Ruxsat yo''q'; end if;return (select qr_token from branches where id=bid);end$$;
alter table branches enable row level security;alter table profiles enable row level security;alter table attendance enable row level security;alter table leaves enable row level security;alter table audit enable row level security;
revoke select on branches from anon,authenticated;grant select(id,name,lat,lng,radius) on branches to authenticated;grant insert,update,delete on branches to authenticated;
create policy b1 on branches for select to authenticated using(true);
create policy b2 on branches for all to authenticated using(is_admin()) with check(is_admin());
create policy p1 on profiles for select to authenticated using(true);
create policy p2 on profiles for all to authenticated using(is_admin()) with check(is_admin());
create policy a1 on attendance for select to authenticated using(user_id=auth.uid() or is_admin());
create policy a2 on attendance for all to authenticated using(is_admin()) with check(is_admin());
create policy l1 on leaves for select to authenticated using(user_id=auth.uid() or is_admin());
create policy l2 on leaves for insert to authenticated with check(user_id=auth.uid() and status='pending');
create policy l3 on leaves for update to authenticated using(is_admin()) with check(is_admin());
create policy u1 on audit for all to authenticated using(is_admin()) with check(is_admin());

create table tasks(id bigserial primary key,user_id uuid references profiles,title text,note text,due date,status text default 'new' check(status in('new','accepted','done','rejected')),created_by uuid references profiles,created_at timestamptz default now());
create table transactions(id bigserial primary key,user_id uuid references profiles,amount numeric,kind text,note text,created_by uuid references profiles,created_at timestamptz default now());
create table trips(id bigserial primary key,driver_id uuid references profiles,title text,owner text,phone text,address text,cargo text,price numeric default 0,status text default 'ontheway' check(status in('ontheway','arrived','done')),collected numeric,arrived_at timestamptz,created_at timestamptz default now());
create table locations(user_id uuid primary key references profiles,lat float8,lng float8,updated_at timestamptz default now());
create table messages(id bigserial primary key,user_id uuid references profiles,body text,created_at timestamptz default now());
alter table tasks enable row level security;alter table transactions enable row level security;alter table trips enable row level security;alter table locations enable row level security;alter table messages enable row level security;
revoke update on tasks from authenticated;grant update(status) on tasks to authenticated;
revoke update on trips from authenticated;grant update(status,collected,arrived_at) on trips to authenticated;
create policy k1 on tasks for select to authenticated using(user_id=auth.uid() or is_admin());
create policy k2 on tasks for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy k3 on tasks for insert to authenticated with check(is_admin());
create policy k4 on tasks for delete to authenticated using(is_admin());
create policy t1 on transactions for select to authenticated using(user_id=auth.uid() or is_admin());
create policy t2 on transactions for insert to authenticated with check(is_admin());
create policy t3 on transactions for delete to authenticated using(is_admin());
create policy r1 on trips for select to authenticated using(driver_id=auth.uid() or is_admin());
create policy r2 on trips for update to authenticated using(driver_id=auth.uid()) with check(driver_id=auth.uid());
create policy r3 on trips for insert to authenticated with check(is_admin());
create policy r4 on trips for delete to authenticated using(is_admin());
create policy o1 on locations for select to authenticated using(user_id=auth.uid() or is_admin());
create policy o2 on locations for insert to authenticated with check(user_id=auth.uid());
create policy o3 on locations for update to authenticated using(user_id=auth.uid());
create policy m1 on messages for select to authenticated using(true);
create policy m2 on messages for insert to authenticated with check(user_id=auth.uid());
alter publication supabase_realtime add table messages;
alter table profiles add column if not exists phone text,add column if not exists birth_date date,add column if not exists position text,add column if not exists off_days int[] default '{0}';
update profiles set off_days=array[off_day::int] where off_day is not null;
alter table branches add column if not exists work_start time default '08:00',add column if not exists work_end time default '19:00';
grant select(work_start,work_end) on branches to authenticated;

alter table profiles add column if not exists telegram_id text;
create function set_my_tg(t text) returns void language sql security definer set search_path=public as $$update profiles set telegram_id=t where id=auth.uid()$$;
alter table tasks add column if not exists photo text;
grant update(status,photo) on tasks to authenticated;
alter table trips add column if not exists arrive_photo text,add column if not exists arrive_note text;
grant update(status,collected,arrived_at,arrive_photo,arrive_note) on trips to authenticated;
create table advance_requests(id bigserial primary key,user_id uuid references profiles,amount numeric,note text,status text default 'pending' check(status in('pending','approved','rejected')),created_at timestamptz default now());
create table cash_handover(id bigserial primary key,driver_id uuid references profiles,amount numeric,created_by uuid references profiles,created_at timestamptz default now());
create table announcements(id bigserial primary key,title text,body text,branch_id int references branches,created_by uuid references profiles,created_at timestamptz default now());
create table ann_reads(announcement_id bigint references announcements on delete cascade,user_id uuid references profiles,primary key(announcement_id,user_id));
alter table advance_requests enable row level security;alter table cash_handover enable row level security;alter table announcements enable row level security;alter table ann_reads enable row level security;
create policy v1 on advance_requests for select to authenticated using(user_id=auth.uid() or is_admin());
create policy v2 on advance_requests for insert to authenticated with check(user_id=auth.uid() and status='pending');
create policy v3 on advance_requests for update to authenticated using(is_admin()) with check(is_admin());
create policy h1 on cash_handover for select to authenticated using(driver_id=auth.uid() or is_admin());
create policy h2 on cash_handover for insert to authenticated with check(is_admin());
create policy n1 on announcements for select to authenticated using(branch_id is null or is_admin() or branch_id=(select branch_id from profiles where id=auth.uid()));
create policy n2 on announcements for all to authenticated using(is_admin()) with check(is_admin());
create policy q1 on ann_reads for select to authenticated using(user_id=auth.uid() or is_admin());
create policy q2 on ann_reads for insert to authenticated with check(user_id=auth.uid());
alter table messages add column if not exists room text default 'all';
drop policy if exists m1 on messages;drop policy if exists m2 on messages;
create policy m1 on messages for select to authenticated using(room='all' or is_admin() or room='b'||(select branch_id from profiles where id=auth.uid())::text);
create policy m2 on messages for insert to authenticated with check(user_id=auth.uid() and (room='all' or is_admin() or room='b'||(select branch_id from profiles where id=auth.uid())::text));
insert into storage.buckets(id,name,public) values('photos','photos',false) on conflict do nothing;
create policy ph1 on storage.objects for insert to authenticated with check(bucket_id='photos');
create policy ph2 on storage.objects for select to authenticated using(bucket_id='photos');

alter table profiles drop constraint if exists profiles_role_check;
alter table profiles add constraint profiles_role_check check(role in('admin','manager','employee','driver'));
alter table profiles add column if not exists leave_days int default 15,add column if not exists device_id text;
alter table attendance add column if not exists photo text,add column if not exists acc float8;
alter table trips add column if not exists sign_photo text,add column if not exists region boolean default false;
grant update(status,collected,arrived_at,arrive_photo,arrive_note,sign_photo) on trips to authenticated;
create table pay_params(user_id uuid primary key references profiles on delete cascade,base_salary numeric default 0,plan numeric default 0,pct_ok numeric default 0,pct_low numeric default 0,rate_city numeric default 0,rate_region numeric default 0,hour_rate numeric default 0);
create table pay_inputs(user_id uuid references profiles on delete cascade,month text,sales numeric default 0,primary key(user_id,month));
create table settings(key text primary key,value text);
create table payslips(user_id uuid references profiles on delete cascade,month text,data jsonb,created_at timestamptz default now(),primary key(user_id,month));
create table expenses(id bigserial primary key,user_id uuid references profiles,amount numeric,note text,photo text,status text default 'pending' check(status in('pending','approved','rejected')),created_at timestamptz default now());
create table feedback(id bigserial primary key,user_id uuid references profiles,body text,created_at timestamptz default now());
create table sos(id bigserial primary key,user_id uuid references profiles,lat float8,lng float8,created_at timestamptz default now());
create table documents(id bigserial primary key,user_id uuid references profiles,title text,path text,created_at timestamptz default now());
create function is_mgr_of(uid uuid) returns boolean language sql security definer stable set search_path=public as $$select exists(select 1 from profiles m join profiles u on u.branch_id=m.branch_id where m.id=auth.uid() and m.role='manager' and u.id=uid)$$;
drop function if exists mark(text,float8,float8,text);
create function mark(k text,la float8,ln float8,tok text,ph text default null,ac float8 default null) returns text language plpgsql security definer set search_path=public as $$
declare p profiles;b branches;d float8;l attendance;
begin
select * into p from profiles where id=auth.uid();
select * into b from branches where qr_token=tok;
if b.id is null then raise exception 'QR kod noto''g''ri'; end if;
if p.branch_id is not null and p.branch_id<>b.id and p.role<>'driver' then raise exception 'Bu boshqa filialning QR kodi'; end if;
d:=12742000*asin(sqrt(power(sin(radians(la-b.lat)/2),2)+cos(radians(b.lat))*cos(radians(la))*power(sin(radians(ln-b.lng)/2),2)));
if d>b.radius then raise exception 'Filial hududidan % m uzoqdasiz',round(d); end if;
select * into l from attendance where user_id=p.id and created_at>=date_trunc('day',now() at time zone 'Asia/Tashkent') at time zone 'Asia/Tashkent' order by created_at desc limit 1;
if k='in' and l.kind='in' then raise exception 'Siz allaqachon "Keldim" bosgansiz'; end if;
if k='out' and (l.id is null or l.kind='out') then raise exception 'Avval "Keldim" bosing'; end if;
insert into attendance(user_id,branch_id,kind,lat,lng,photo,acc) values(p.id,b.id,k,la,ln,ph,ac);
return 'ok';end$$;
create function touch_device(d text) returns text language plpgsql security definer set search_path=public as $$
declare cur text;begin select device_id into cur from profiles where id=auth.uid();
if cur is null then update profiles set device_id=d where id=auth.uid();return 'ok';end if;
if cur=d then return 'ok';end if;
insert into audit(actor,action,detail) values(auth.uid(),'Boshqa qurilmadan kirdi','');return 'diff';end$$;
alter table pay_params enable row level security;alter table pay_inputs enable row level security;alter table settings enable row level security;alter table payslips enable row level security;
alter table expenses enable row level security;alter table feedback enable row level security;alter table sos enable row level security;alter table documents enable row level security;
create policy y1 on pay_params for all to authenticated using(is_admin()) with check(is_admin());
create policy y2 on pay_inputs for all to authenticated using(is_admin()) with check(is_admin());
create policy y3 on settings for all to authenticated using(is_admin()) with check(is_admin());
create policy y4 on payslips for select to authenticated using(user_id=auth.uid() or is_admin());
create policy y5 on payslips for all to authenticated using(is_admin()) with check(is_admin());
create policy e1 on expenses for select to authenticated using(user_id=auth.uid() or is_admin());
create policy e2 on expenses for insert to authenticated with check(user_id=auth.uid() and status='pending');
create policy e3 on expenses for update to authenticated using(is_admin()) with check(is_admin());
create policy f1 on feedback for insert to authenticated with check(user_id is null or user_id=auth.uid());
create policy f2 on feedback for select to authenticated using(is_admin());
create policy s1 on sos for insert to authenticated with check(user_id=auth.uid());
create policy s2 on sos for select to authenticated using(is_admin() or is_mgr_of(user_id));
create policy d1 on documents for select to authenticated using(user_id=auth.uid() or is_admin());
create policy d2 on documents for all to authenticated using(is_admin()) with check(is_admin());
create policy a3 on attendance for select to authenticated using(is_mgr_of(user_id));
create policy l4 on leaves for select to authenticated using(is_mgr_of(user_id));
create policy l5 on leaves for update to authenticated using(is_mgr_of(user_id)) with check(is_mgr_of(user_id));
create policy k5 on tasks for select to authenticated using(is_mgr_of(user_id));
create policy k6 on tasks for insert to authenticated with check(is_mgr_of(user_id));
create policy k7 on tasks for delete to authenticated using(is_mgr_of(user_id));
create policy n3 on announcements for insert to authenticated with check(branch_id is not null and exists(select 1 from profiles where id=auth.uid() and role='manager' and branch_id=announcements.branch_id));
insert into storage.buckets(id,name,public) values('docs','docs',false) on conflict do nothing;
create policy dc1 on storage.objects for insert to authenticated with check(bucket_id='docs' and is_admin());
create policy dc2 on storage.objects for select to authenticated using(bucket_id='docs' and (is_admin() or (storage.foldername(name))[1]=auth.uid()::text));
drop policy if exists ph2 on storage.objects;
create policy ph3 on storage.objects for select to authenticated using(bucket_id='photos' and ((storage.foldername(name))[1]=auth.uid()::text or is_admin() or is_mgr_of(((storage.foldername(name))[1])::uuid)));
